import { readFileSync, realpathSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const compare = (a, b) => a < b ? -1 : a > b ? 1 : 0;
const isId = value => typeof value === 'string' && value.length > 0;

export function planJobs(spec) {
  if (!Array.isArray(spec)) throw new Error('Expected an array of jobs');
  const jobs = new Map();
  for (const job of spec) {
    if (job === null || typeof job !== 'object' || Array.isArray(job) ||
        !isId(job.id) || !Array.isArray(job.deps) ||
        !['pending', 'succeeded', 'failed'].includes(job.state)) {
      throw new Error('Invalid job fields');
    }
    if (jobs.has(job.id)) throw new Error('Duplicate job ID');
    const deps = new Set();
    for (const dep of job.deps) {
      if (!isId(dep) || deps.has(dep)) throw new Error('Invalid or duplicate dependency');
      deps.add(dep);
    }
    jobs.set(job.id, {
      id: job.id, state: job.state, deps: [...deps],
      children: [], remaining: deps.size, causes: new Set(),
    });
  }
  for (const job of jobs.values()) {
    for (const dep of job.deps) {
      if (!jobs.has(dep)) throw new Error('Unknown dependency');
      jobs.get(dep).children.push(job.id);
    }
  }

  // Keep the frontier sorted, inserting newly released jobs before choosing again.
  const frontier = [...jobs.values()].filter(job => job.remaining === 0)
    .map(job => job.id).sort(compare);
  const insert = id => {
    let lo = 0, hi = frontier.length;
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (compare(frontier[mid], id) < 0) lo = mid + 1;
      else hi = mid;
    }
    frontier.splice(lo, 0, id);
  };
  const fullOrder = [];
  while (frontier.length) {
    const id = frontier.shift();
    const job = jobs.get(id);
    fullOrder.push(id);
    for (const childId of job.children) {
      const child = jobs.get(childId);
      // Ancestry propagates across every state, including completed jobs.
      for (const cause of job.causes) child.causes.add(cause);
      if (job.state === 'failed') child.causes.add(id);
      if (--child.remaining === 0) insert(childId);
    }
  }
  if (fullOrder.length !== jobs.size) throw new Error('Dependency cycle');

  const order = [], ready = [], blocked = [];
  for (const id of fullOrder) {
    const job = jobs.get(id);
    if (job.state !== 'pending') continue;
    if (job.causes.size) {
      blocked.push({ id, causes: [...job.causes].sort(compare) });
    } else {
      order.push(id);
      if (job.deps.every(dep => jobs.get(dep).state === 'succeeded')) ready.push(id);
    }
  }
  ready.sort(compare);
  blocked.sort((a, b) => compare(a.id, b.id));
  return { order, ready, blocked };
}

function isMain() {
  if (!process.argv[1]) return false;
  try {
    return realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url));
  } catch {
    return false;
  }
}

if (isMain()) {
  try {
    if (process.argv.length !== 3) throw new Error('Usage: node job-plan.js SPECFILE');
    const spec = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    process.stdout.write(JSON.stringify(planJobs(spec)) + '\n');
  } catch (error) {
    process.stderr.write(`job-plan: ${error.message}\n`);
    process.exitCode = 2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });

test('full graph ordering is filtered only after Kahn traversal', () => {
  const spec = [job('a', ['z']), job('b'), job('z', [], 'succeeded')];
  assert.deepEqual(planJobs(spec), { order: ['b', 'a'], ready: ['a', 'b'], blocked: [] });
  assert.deepEqual(planJobs([...spec].reverse()), planJobs(spec));
});

test('all failed ancestry survives succeeded and failed intermediates', () => {
  assert.deepEqual(planJobs([
    job('root', [], 'failed'), job('second', ['root'], 'failed'),
    job('ok', ['second'], 'succeeded'), job('z', ['ok', 'root']),
    job('a', ['z', 'second']), job('free'), job('later', ['free']),
  ]), {
    order: ['free', 'later'], ready: ['free'],
    blocked: [{ id: 'a', causes: ['root', 'second'] }, { id: 'z', causes: ['root', 'second'] }],
  });
});

test('exact IDs, code-unit sorting, ignored fields and immutable input', () => {
  const ids = ['é', 'a', 'Z', '😀', '\ue000', '__proto__', 'constructor', ' ', ' a '];
  const spec = ids.map(id => Object.freeze({ ...job(id), deps: Object.freeze([]), extra: 42 }));
  Object.freeze(spec);
  const sorted = [...ids].sort();
  assert.deepEqual(planJobs(spec), { order: sorted, ready: sorted, blocked: [] });
  assert.deepEqual(planJobs([job('__proto__'), job('constructor', ['__proto__'])]), {
    order: ['__proto__', 'constructor'], ready: ['__proto__'], blocked: [],
  });
});

test('malformed specs and fields throw synchronously', () => {
  const invalid = [
    null, {}, 'jobs', 42, [null], [42], [[]], [{}],
    [{ id: '', deps: [], state: 'pending' }],
    [{ id: 1, deps: [], state: 'pending' }],
    [{ id: 'x', state: 'pending' }],
    [{ id: 'x', deps: null, state: 'pending' }],
    [{ id: 'x', deps: 'y', state: 'pending' }],
    [{ id: 'x', deps: [] }],
    [{ id: 'x', deps: [], state: undefined }],
    [{ id: 'x', deps: [], state: 'Pending' }],
    [job('x', [''])], [job('x', [1])], [job('x', [null])],
    [job('x', ['y', 'y']), job('y')], [job('x'), job('x')],
    [job('x', ['missing'])], [job('x', new Array(1))], new Array(1),
  ];
  for (const spec of invalid) assert.throws(() => planJobs(spec), Error);
});

test('cycles anywhere are invalid, irrespective of states', () => {
  for (const state of ['pending', 'succeeded', 'failed']) {
    assert.throws(() => planJobs([job('x', ['x'], state)]), Error);
    assert.throws(() => planJobs([
      job('free'), job('x', ['y'], state), job('y', ['x'], 'succeeded'),
    ]), Error);
  }
});

const cli = fileURLToPath(new URL('../job-plan.js', import.meta.url));
const run = args => spawnSync(process.execPath, args, { encoding: 'utf8' });
const assertFailure = result => {
  assert.equal(result.error, undefined);
  assert.equal(result.status, 2);
  assert.equal(result.stdout, '');
  assert.ok(result.stderr.trim().length > 0);
};

test('CLI success and every failure category use the specified streams and status', () => {
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-test-'));
  try {
    const path = join(dir, 'spec.json');
    writeFileSync(path, JSON.stringify([job('é'), job('next', ['é'])]));
    const result = run([cli, path]);
    assert.equal(result.error, undefined);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, JSON.stringify({ order: ['é', 'next'], ready: ['é'], blocked: [] }) + '\n');
    assertFailure(run([cli]));
    assertFailure(run([cli, path, path]));
    assertFailure(run([cli, join(dir, 'absent')]));
    assertFailure(run([cli, dir]));
    writeFileSync(path, '{invalid json');
    assertFailure(run([cli, path]));
    writeFileSync(path, JSON.stringify([job('x', ['x'], 'succeeded')]));
    assertFailure(run([cli, path]));
    writeFileSync(path, '{}');
    assertFailure(run([cli, path]));
    writeFileSync(path, '[]');
    const empty = run([cli, path]);
    assert.equal(empty.status, 0);
    assert.equal(empty.stderr, '');
    assert.equal(empty.stdout, '{"order":[],"ready":[],"blocked":[]}\n');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('module import has no CLI side effects', () => {
  const url = new URL('../job-plan.js', import.meta.url).href;
  const result = run(['--input-type=module', '-e', `const m = await import(${JSON.stringify(url)}); if (typeof m.planJobs !== 'function') process.exit(1);`]);
  assert.equal(result.status, 0);
  assert.equal(result.stdout, '');
  assert.equal(result.stderr, '');
});

