import assert from 'node:assert/strict';
import test from 'node:test';
import {pathToFileURL} from 'node:url';
import path from 'node:path';
const {planJobs}=await import(pathToFileURL(path.resolve(process.env.CANDIDATE_ROOT,'job-plan.js')));
const compare=(a,b)=>a<b?-1:a>b?1:0;
function permutations(a){return a.length ? a.flatMap((v,i)=>permutations(a.filter((_,j)=>j!==i)).map(t=>[v,...t])) : [[]];}
const ids=['🐓','constructor','__proto__',' '];
const orders=permutations([...ids].sort(compare));
function reference(spec){
 const jobs=new Map(spec.map(j=>[j.id,j]));
 // Enumerate complete orders independently of the candidate's Kahn traversal.
 const order=orders.find(p=>spec.every(j=>j.deps.every(d=>p.indexOf(d)<p.indexOf(j.id))));
 const blocked=spec.filter(j=>j.state==='pending').map(j=>{
  const reached=new Set(),todo=[...j.deps];
  for(let i=0;i<todo.length;i++)if(!reached.has(todo[i])){
   reached.add(todo[i]);todo.push(...jobs.get(todo[i]).deps);
  }
  return {id:j.id,causes:[...reached].filter(id=>jobs.get(id).state==='failed').sort(compare)};
 }).filter(j=>j.causes.length).sort((a,b)=>compare(a.id,b.id));
 const blockedIds=new Set(blocked.map(j=>j.id));
 return {order:order.filter(id=>jobs.get(id).state==='pending'&&!blockedIds.has(id)),
  ready:spec.filter(j=>j.state==='pending'&&!blockedIds.has(j.id)&&j.deps.every(d=>jobs.get(d).state==='succeeded')).map(j=>j.id).sort(compare),blocked};
}
test('5,184 dependency graphs and state assignments agree with an independent exhaustive-order oracle',()=>{
 const edges=ids.flatMap((_,i)=>ids.flatMap((_,j)=>i<j?[[i,j]]:[]));
 let cases=0;
 for(let mask=0;mask<64;mask++)for(let states=0;states<81;states++){
  let n=states;
  const spec=ids.map(id=>{const state=['pending','succeeded','failed'][n%3];n=Math.floor(n/3);return {id,state,deps:[],future:{ignored:true}};});
  edges.forEach(([dep,child],bit)=>{if(mask&(1<<bit))spec[child].deps.push(ids[dep]);});
  spec.reverse();const expected=reference(spec);
  for(const job of spec){Object.freeze(job.future);Object.freeze(job.deps);Object.freeze(job);}Object.freeze(spec);
  assert.deepEqual(planJobs(spec),expected,`edge mask ${mask}, states ${states}`);cases++;
 }
 assert.equal(cases,5184);
});
test('a 5,000-job dependency chain completes without recursive-stack failure',()=>{
 const ids=Array.from({length:5000},(_,i)=>String(i).padStart(5,'0'));
 const spec=ids.map((id,i)=>({id,state:'pending',deps:i?[ids[i-1]]:[]})).reverse();
 assert.deepEqual(planJobs(spec),{order:ids,ready:[ids[0]],blocked:[]});
});
test('a broad 2,000-job ready frontier preserves code-unit ordering',()=>{
 const ids=Array.from({length:2000},(_,i)=>`job-${i}`),expected=[...ids].sort(compare);
 const spec=ids.map(id=>({id,state:'pending',deps:[]})).reverse();
 assert.deepEqual(planJobs(spec),{order:expected,ready:expected,blocked:[]});
});
